update PA_PTL_PORTFOLIO T1


	 	T1.RAISE_TYPE = #{raisetype,jdbcType=VARCHAR},


where T1.PORTFOLIO_ID = (SELECT T2.FINPROD_MARKET_ID
					     FROM FIN_PRODUCT T2
					     WHERE T2.FINPROD_ID=#{finprodId,jdbcType=VARCHAR}
					    )

