SELECT
       PORTFOLIO_ID
FROM RSK_PORTFOLIO_INDICATOR
WHERE PORTFOLIO_ID = #{portfolioId,jdbcType=VARCHAR}
  AND START_DATE <= #{sysDate,jdbcType=VARCHAR}
  AND ( END_DATE >= #{sysDate,jdbcType=VARCHAR}
        OR END_DATE IS NULL)
